import sys

def main():
    import sys
    import collections
    import heapq

    input = sys.stdin.read().split()
    n = int(input[0])
    a = list(map(int, input[1:]))

    degree = [0] * (n + 1)
    parent = [0] * (n + 1)
    children = collections.defaultdict(list)

    for main in a:
        degree[main] += 1

    queue = []
    for i in range(1, n + 1):
        if degree[i] == 0:
            heapq.heappush(queue, i)

    root_candidates = []
    for i in range(1, n + 1):
            if degree[i] == 0:
                root_candidates.append(i)

    if len(root_candidates) != 1:
        print(-1)
        return

    root = root_candidates[0]
    for main in reversed(a):
        if not queue:
            print(-1)
            return
        child = heapq.heappop(queue)
        parent[child] = main
        children[main].append(child)
        degree[main] -= 1
        if degree[main] == 0:
            heapq.heappush(queue, main)

    if any(degree[i] > 0 for i in range(1, n + 1)):
        print(-1)
        return

    def dfs(node):
        for child in children[node]:
            yield node, child
            yield from dfs(child)

    print(root)
    for x, y in dfs(root):
        print(x, y)

if __name__ == "__main__":
    main()
